cat > /tmp/roundfix.test.mjs <<'EOF'
import { test } from "node:test";
import assert from "node:assert";
const roundCents = (x) => Math.round((x + Number.EPSILON) * 100) / 100;
test("rounds half up", () => assert.strictEqual(roundCents(1.005), 1.01));
test("rounds down", () => assert.strictEqual(roundCents(1.234), 1.23));
test("no epsilon inflation", () => assert.strictEqual(roundCents(1.004999), 1.0));
test("2.675 edge", () => assert.strictEqual(roundCents(2.675), 2.68));
EOF
node --test /tmp/roundfix.test.mjs 2>&1 | tail -8
